type IconName = 'user' | 'shield' | 'bell' | 'globe' | 'arrow' | 'chevron' | 'upload' | 'check' | 'help' | 'mail' | 'close' | 'menu' | 'sun';
function Icon({name, size = 20, className = ''}: {name: IconName; size?: number; className?: string}) {
